const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);let lang=params.get('lang')==='en'?'en':'fr',tab=params.get('view')||'dashboard',tenant=params.get('brand')==='boreal'?'boreal':'maison',embed=params.get('embed')==='1';
const tr=(f,e)=>lang==='fr'?f:e;
let brands={maison:{name:'Maison & Marché',color:'#126953',letter:'M',branches:['Saint-Sauveur','Sainte-Adèle','Prévost'],plan:0},boreal:{name:'Boréal Hôtels',color:'#304b83',letter:'B',branches:['Saint-Sauveur','Mont-Tremblant'],plan:0}};
let jobs=[{id:1,brand:'maison',role:0,city:'Saint-Sauveur',date:'2026-11-03',start:'12:00',end:'16:00',pay:22,scope:'network',filled:false},{id:2,brand:'maison',role:1,city:'Sainte-Adèle',date:'2026-11-04',start:'16:00',end:'21:00',pay:23,scope:'network',filled:false},{id:3,brand:'boreal',role:2,city:'Mont-Tremblant',date:'2026-11-03',start:'09:00',end:'15:00',pay:25,scope:'network',filled:false}];
let applications=[],filter='all',consent=null;let workerAvailability=[];let networkProfile={skillIds:[],licenceClasses:[],phone:''};let reviewDraft=null;
DispoStandards.seed('employer:maison',4.6,18);DispoStandards.seed('employer:boreal',4.9,24);DispoStandards.seed('worker:network-alex',4.7,15);
const roles=()=>[tr('Commis de commerce','Retail associate'),tr('Aide en cuisine','Kitchen assistant'),tr('Préposé·e à l’entretien','Housekeeping associate'),tr('Manutentionnaire','Warehouse associate')];
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function toggleLanguage(){lang=lang==='fr'?'en':'fr';render()}
function navigate(v){tab=v;consent=null;render();window.scrollTo(0,0)}
function render(){if(!['dashboard','brand','profile','portal','network','integrate','plans'].includes(tab))tab='dashboard';document.documentElement.lang=lang;document.documentElement.style.setProperty('--brand',tab==='network'?'#7356cf':brands[tenant].color);document.body.className=embed?'embed':'';let b=brands[tenant];$('#app').innerHTML=`<div class="demo">${tr('DÉMO MARQUE BLANCHE · Enseignes fictives · Actions simulées · Publications temporaires · Modèles dans ce navigateur','WHITE-LABEL DEMO · Fictional brands · Simulated actions · Temporary posts · Templates in this browser')}</div><header class="top"><a href="/" class="logo">dispo<b>•</b><span>ENTREPRISES</span></a><div class="right"><select aria-label="${tr('Enseigne de démonstration','Demo brand')}" onchange="tenant=this.value;render()">${Object.entries(brands).map(([k,v])=>`<option value="${k}" ${tenant===k?'selected':''}>${esc(v.deleted?tr('Profil effacé','Deleted profile'):v.name)}</option>`).join('')}</select><button class="secondary small" onclick="toggleLanguage()">${lang==='fr'?'EN':'FR'}</button></div></header><div class="shell"><aside><div class="eyebrow">${tr('Espace entreprise','Business workspace')}</div><nav>${[['dashboard','▦',tr('Vue d’ensemble','Overview')],['profile','◯',tr('Profil entreprise','Business profile')],['brand','◈',tr('Votre marque','Your brand')],['portal','↗',tr('Portail de l’enseigne','Brand portal')],['network','◎',tr('Réseau employés','Worker network')],['integrate','⌘',tr('Diffusion & intégration','Share & embed')],['plans','▤',tr('Abonnement entreprise','Business subscription')]].map(([k,i,l])=>`<button class="${tab===k?'active':''}" onclick="navigate('${k}')">${i} &nbsp;${l}</button>`).join('')}</nav><div class="side-note">${tr('Votre identité.<br>Vos succursales.<br>Un réseau Dispo commun.','Your identity.<br>Your locations.<br>One shared Dispo network.')}<p>${tr('Le changement d’enseigne est réservé à cette démo.','Brand switching is a demo control.')}</p><a href="/">${tr('Démo Dispo classique','Original Dispo demo')} ↗</a></div></aside><main>${brands[tenant].deleted&&tab!=='network'?deletedBrandPage():({dashboard,brand:branding,profile:businessProfile,portal,network,integrate,plans}[tab])()}<footer>${tr('Aucune paie ne transite par Dispo. Le paiement convenu est effectué directement par l’employeur. Aucun abonnement réel n’est vendu ici.','Dispo does not process wages. Agreed payment is made directly by the employer. No real subscription is sold here.')}<br>${tr('Prototype : pas de comptes réels, de notifications, de facturation ni de partage entre appareils. La séparation sécurisée des entreprises reste à développer avant exploitation.','Prototype: no real accounts, notifications, billing or cross-device sharing. Secure tenant isolation must be implemented before production.')}</footer></main></div>`;document.querySelectorAll('label').forEach((l,i)=>{const n=l.nextElementSibling;if(n&&['INPUT','SELECT'].includes(n.tagName)){n.id=n.id||'field-'+i;l.htmlFor=n.id}});}
function heading(k,h,p,action=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${h}</h1><p>${p}</p></div>${action}</div>`}
function dashboard(){let b=brands[tenant],own=jobs.filter(j=>j.brand===tenant),apps=applications.filter(a=>own.some(j=>j.id===a.job));return heading(tr('Pilotage multisite','Multi-location operations'),tr('Les bons renforts. À votre enseigne.','The right support. Under your brand.'),tr('Publiez un besoin local. Retrouvez-le dans le réseau Dispo.','Publish a local shift. See it in the Dispo network.'),`<button onclick="openBrandPlanner()">+ ${tr('Publier un quart','Post a shift')}</button>`)+`<div class="grid"><div class="card"><div class="eyebrow">${tr('Succursales de démonstration','Demo locations')}</div><span class="stat">${b.branches.length}</span><span class="sub">${b.branches.join(' · ')}</span></div><div class="card"><div class="eyebrow">${tr('Quarts ouverts','Open shifts')}</div><span class="stat">${own.filter(j=>!j.filled).length}</span><span class="sub">${tr('Dans votre enseigne','Within your brand')}</span></div><div class="card"><div class="eyebrow">${tr('Candidatures simulées','Simulated applications')}</div><span class="stat">${apps.length}</span><span class="sub">${tr('Uniquement pour votre enseigne','Only for your brand')}</span></div></div><div class="two section"><section class="card" id="publish"><h2>${tr('Un besoin dans une succursale ?','Need someone at a location?')}</h2><p>${tr('Un même poste, plusieurs dates et plusieurs succursales. Créez vos quarts en une seule opération.','One role, several dates and several locations. Create your shifts in one step.')}</p><button onclick="openBrandPlanner()">+ ${tr('Planifier / charger un modèle','Plan / load a template')}</button><div class="notice">${tr('Dates au choix · répétition hebdomadaire · mois complet · plusieurs créneaux par jour.','Choose dates · weekly repeat · entire month · several slots per day.')}</div><p class="sub">${tr('Les modèles sont conservés dans ce navigateur, séparément pour chaque enseigne. Les quarts publiés restent temporaires.','Templates are saved in this browser, separately for each brand. Published shifts remain temporary.')}</p></section><section class="card"><h2>${tr('Vos quarts','Your shifts')}</h2><div style="max-height:460px;overflow:auto">${own.slice().reverse().map(j=>`<div class="listrow"><div><strong>${roles()[j.role]}</strong><div class="sub">${esc(j.city)} · ${esc(j.date)} · ${j.start}–${j.end}</div><div class="sub">${j.count||1} ${tr('personne(s)','person(s)')}${j.sameTeam?' · '+tr('Mêmes employés souhaités','Same workers preferred'):''}</div><div class="sub">${j.scope==='network'?tr('Portail + Dispo','Portal + Dispo'):tr('Portail seulement','Portal only')}</div></div><div class="row"><button class="secondary small" onclick="openBrandPlanner(${j.id})">${tr('Réutiliser / enregistrer','Reuse / save')}</button><button class="secondary small" onclick="toggleFilled(${j.id})">${j.filled?tr('✓ Comblé · rouvrir','✓ Filled · reopen'):tr('Marquer comblé','Mark filled')}</button></div></div>`).join('')}</div>${seriesControls()}<h2 class="section">${tr('Candidatures','Applications')}</h2>${DispoStandards.encourage(lang)}${DispoStandards.reviewPreview('employee',lang)}${reviewDraft?.actor==='employer'?businessReviewForm():''}${apps.length?apps.map(a=>`<div class="listrow"><div><strong>${tr('Alex · profil fictif','Alex · fictional profile')}</strong><div class="sub">${roles()[jobs.find(j=>j.id===a.job).role]}</div></div><div>${DispoStandards.badge('worker:network-alex',lang)}${DispoStandards.skillsSummary(networkProfile,lang)}${applicationReviewControls(a,'employer')}</div></div>`).join(''):`<div class="notice">${tr('Testez une candidature depuis « Réseau employés », puis revenez ici.','Try applying from “Worker network”, then return here.')}</div>`}</section></div>`}
function publishJob(e){e.preventDefault();let f=new FormData(e.target);if(f.get('end')<=f.get('start'))return toast(tr('La fin doit être après le début pour ce quart de jour.','End time must be after start time for this same-day shift.'));jobs.push({id:Date.now(),brand:tenant,role:+f.get('role'),city:f.get('city'),date:f.get('date'),start:f.get('start'),end:f.get('end'),pay:+f.get('pay'),scope:f.get('scope'),filled:false});render();toast(tr('Quart publié dans la démo.','Shift published in the demo.'))}
function toggleFilled(id){let j=jobs.find(j=>j.id===id);j.filled=!j.filled;render()}
function branding(){let b=brands[tenant];return heading(tr('Personnalisation','Customization'),tr('Votre marque, au premier plan.','Your brand, front and centre.'),tr('Adaptez le portail à l’identité de votre réseau.','Make the portal reflect your organization.'))+`<div class="two"><form class="card" onsubmit="saveBrand(event)"><h2>${tr('Identité visuelle','Brand identity')}</h2><label>${tr('Nom de l’enseigne','Brand name')}</label><input name="name" maxlength="40" required value="${esc(b.name)}"><div class="formgrid"><div><label>${tr('Monogramme du logo','Logo monogram')}</label><input name="letter" maxlength="2" required value="${esc(b.letter)}"></div><div><label>${tr('Couleur principale','Primary colour')}</label><input type="color" name="color" value="${b.color}"></div></div><label>${tr('Succursales · séparées par une virgule','Locations · separated by commas')}</label><input name="branches" required value="${esc(b.branches.join(', '))}"><p class="sub">${tr('Les offres existantes conservent leur succursale d’origine.','Existing shifts keep their original location.')}</p><button>${tr('Appliquer à la démo','Apply to demo')}</button></form><div><div class="card"><div class="brandhead"><div class="mark">${esc(b.letter)}</div><strong>${esc(b.name)}</strong></div><h1>${tr('Votre prochain quart<br>commence ici.','Your next shift<br>starts here.')}</h1><p>${tr('Découvrez les besoins de nos équipes près de chez vous.','Find openings with our teams near you.')}</p><button onclick="navigate('portal')">${tr('Voir mon portail','View my portal')} ↗</button></div><div class="notice">${tr('En production : logo complet et domaine de l’enseigne à configurer. L’aperçu utilise un monogramme et un lien de démonstration.','In production: configure a full logo and branded domain. This preview uses a monogram and a demo link.')}</div></div></div>`}
function saveBrand(e){e.preventDefault();let f=new FormData(e.target);let bs=f.get('branches').split(',').map(s=>s.trim()).filter(Boolean).slice(0,30);if(!f.get('name').trim()||!bs.length)return;Object.assign(brands[tenant],{name:f.get('name').trim(),letter:f.get('letter').trim(),color:f.get('color'),branches:bs});render();toast(tr('Identité mise à jour dans cet onglet.','Brand updated in this tab.'))}
function card(j){let b=brands[j.brand],applied=applications.some(a=>a.job===j.id);return `<article class="card job"><div class="row spread"><span class="tenantline">${esc(b.name)}</span><span class="badge ${j.filled?'gray':''}">${j.filled?tr('✓ Offre comblée','✓ Shift filled'):tr('Quart disponible','Open shift')}</span></div><h3>${roles()[j.role]}</h3>${DispoStandards.badge('employer:'+j.brand,lang)}${DispoStandards.skillsSummary(b,lang)}<p>⌖ ${esc(j.city)}<br>◷ ${esc(j.date)} · ${j.start}–${j.end}</p><div class="sub">${j.count||1} ${tr('personne(s) recherchée(s)','opening(s)')}${j.sameTeam?' · '+tr('Même équipe souhaitée','Same team preferred'):''}</div><div class="pay">${j.pay} $ <span class="sub">${tr('brut / h','gross / h')}</span></div><button ${j.filled||applied?'disabled':''} onclick="consent=${j.id};render();$('#consent').scrollIntoView({behavior:'smooth'})">${applied?tr('✓ Candidature simulée envoyée','✓ Simulated application sent'):j.filled?tr('Plus disponible','No longer available'):tr('Ce quart m’intéresse','I’m interested')}</button></article>`}
function consentBox(){if(!consent)return '';let j=jobs.find(j=>j.id===consent);return `<form class="card section" id="consent" onsubmit="applyJob(event,${j.id})"><h2>${tr('Un profil. Un partage choisi.','One profile. Sharing you control.')}</h2><p>${tr('Le profil fictif Alex sera partagé avec','The fictional Alex profile will be shared with')} <strong>${esc(brands[j.brand].name)}</strong> ${tr('pour ce quart seulement. Les autres enseignes ne reçoivent pas cette candidature.','for this shift only. Other brands do not receive this application.')}</p><label class="checks"><input type="checkbox" required> ${tr('J’accepte de partager ce profil de démonstration et mes disponibilités pour cette candidature.','I agree to share this demo profile and availability for this application.')}</label><div class="row"><button>${tr('Confirmer la candidature simulée','Confirm simulated application')}</button><button type="button" class="secondary" onclick="consent=null;render()">${tr('Annuler','Cancel')}</button></div></form>`}
function applyJob(e,id){e.preventDefault();if(!applications.some(a=>a.job===id))applications.push({job:id});consent=null;render();toast(tr('Candidature ajoutée au tableau de bord de cette enseigne.','Application added to this brand’s dashboard.'))}
function portal(){let b=brands[tenant];return `<div class="brandhead" style="margin-bottom:25px"><div class="mark">${esc(b.letter)}</div><strong>${esc(b.name)}</strong><span class="badge">${tr('Enseigne fictive','Fictional brand')}</span></div><section class="hero"><div class="hero-art">${esc(b.letter)}</div><div class="eyebrow">${tr('Des équipes locales. De nouvelles possibilités.','Local teams. New possibilities.')}</div><h1>${tr('Un peu de temps ?<br>Faites équipe avec nous.','Have a little time?<br>Join our team.')}</h1><p>${tr('Des quarts ponctuels dans nos succursales. Choisissez ce qui convient à votre horaire.','Occasional shifts at our locations. Choose what fits your schedule.')}</p><span class="badge">${tr('Votre profil Dispo vous accompagne','Bring your Dispo profile')}</span></section><div class="heading section"><h2>${tr('Les quarts de notre enseigne','Our brand’s shifts')}</h2><span class="sub">${tr('Paiement direct par l’employeur','Direct payment by the employer')}</span></div><div class="grid">${jobs.filter(j=>j.brand===tenant).map(card).join('')}</div>${consentBox()}<div class="notice">${tr('Les enseignes sont identifiées sur leur propre portail. Votre profil n’est communiqué qu’après votre accord.','Brands are identified on their own portal. Your profile is shared only with your agreement.')} <a href="?view=network">${tr('Découvrir le réseau Dispo','Explore the Dispo network')} ↗</a></div>`}
function network(){let shown=DispoStandards.rank(jobs.filter(j=>j.scope==='network'&&!brands[j.brand].deleted&&(filter==='all'||j.brand===filter)),j=>'employer:'+j.brand);return heading('DISPO · '+tr('ESPACE EMPLOYÉ','WORKER SPACE'),tr('Un seul profil. Plusieurs enseignes.','One profile. Many brands.'),tr('Votre espace reste gratuit. Vous choisissez où et avec qui travailler.','Your space stays free. Choose where and with whom to work.'))+`<div class="card row spread"><div><span class="badge purple">${tr('Alex · profil fictif','Alex · fictional profile')}</span><p style="margin:8px 0 0">${tr('Commerce · Cuisine · Disponibilité : midi à 21 h','Retail · Kitchen · Available: noon–9 pm')}</p></div><span class="sub">${applications.length} ${tr('candidature(s) simulée(s)','simulated application(s)')}</span></div><div class="row section"><label for="filter">${tr('Enseigne','Brand')}</label><select id="filter" style="width:auto" onchange="filter=this.value;render()"><option value="all">${tr('Toutes les enseignes','All brands')}</option>${Object.entries(brands).map(([k,b])=>`<option value="${k}" ${filter===k?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div>${networkProfileForm()}${availabilityPanel()}${networkReviews()}${DispoStandards.explanation(lang)}<div class="grid section">${shown.map(card).join('')}</div>${consentBox()}<div class="notice">${tr('Vos candidatures restent indépendantes. Une enseigne ne voit ni votre activité ni vos échanges avec une autre. Dans cette démo, cette séparation est visuelle; elle devra être sécurisée côté serveur.','Applications stay independent. A brand cannot see your activity or conversations with another brand. In this demo this separation is visual; it must be enforced on the server in production.')}</div>`}
function portalURL(){return location.origin+location.pathname+'?view=portal&brand='+tenant+'&lang='+lang}
function integrate(){let url=portalURL(),code='<iframe src="'+url+'&embed=1" title="'+esc(brands[tenant].name)+' — '+tr('Quarts disponibles','Available shifts')+'" width="100%" height="850" style="border:0" loading="lazy"></iframe>';return heading(tr('Diffusion','Distribution'),tr('Votre portail, là où sont vos candidats.','Your portal, where your candidates are.'),tr('Un même point d’entrée depuis votre site et vos médias sociaux.','One entry point from your website and social channels.'))+`<div class="two"><section class="card"><span class="badge">01 · ${tr('SITE WEB','WEBSITE')}</span><h2 class="section">${tr('Bouton ou module intégré','Button or embedded module')}</h2><p>${tr('Ajoutez un bouton « Voir les quarts disponibles » à votre page carrière. Le module ci-dessous permet de tester un affichage intégré.','Add a “View available shifts” button to your careers page. Use the code below to test an embedded view.')}</p><textarea id="embedcode" readonly aria-label="Code iframe">${esc(code)}</textarea><button class="secondary small" onclick="copyText($('#embedcode').value)">${tr('Copier le code','Copy code')}</button><p class="sub">${tr('À tester sur le site cible selon ses règles de sécurité. Domaine personnalisé et connexion réelle à configurer en production.','Test on the destination website under its security rules. Custom domain and real sign-in require production setup.')}</p></section><section class="card"><span class="badge">02 · ${tr('MÉDIAS SOCIAUX','SOCIAL MEDIA')}</span><h2 class="section">${tr('Un lien dans votre bio ou publication','A link in your bio or post')}</h2><p>Instagram · Facebook · LinkedIn · TikTok</p><div class="linkbox" id="shareurl">${esc(url)}</div><div class="row section"><button onclick="copyText(portalURL())">${tr('Copier le lien','Copy link')}</button><a href="${esc(url)}" target="_blank" rel="noopener">${tr('Ouvrir le portail','Open portal')} ↗</a></div><p class="sub">${tr('Le lien ouvre le portail dans un navigateur. L’application n’est pas hébergée directement dans les réseaux sociaux. Les personnalisations de cet onglet ne sont pas transférées dans le lien.','The link opens the portal in a browser. The app is not hosted inside social networks. Customizations made in this tab are not transferred in the link.')}</p></section></div><div class="notice"><strong>${tr('Avant une mise en service commerciale','Before commercial launch')}</strong><br>${tr('Prévoir : comptes et droits par succursale, base de données cloisonnée, accord de partage des profils, notifications, facturation des abonnements, domaine et intégration. Aucun de ces services n’est activé par ce prototype.','Plan for: location-level accounts and permissions, tenant-isolated data, profile-sharing consent, notifications, subscription billing, domain and integration. None of these services is activated by this prototype.')}</div>`}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast(tr('Copié.','Copied.'))}catch{toast(tr('Copie indisponible : sélectionnez le texte affiché.','Copy unavailable: select the displayed text.'))}}
const planLimits=[{locations:3,shifts:150},{locations:15,shifts:1000},{locations:null,shifts:null}];
function planMonth(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function planUsage(owner){return jobs.filter(j=>j.brand===owner&&j.publishedMonth===planMonth()).length}
function freshBrandRows(rows,owner){return rows.filter(r=>!jobs.some(j=>j.brand===owner&&j.role===Number(r.roleKey)&&j.city===r.city&&j.date===r.date&&j.start===r.start&&j.end===r.end&&!j.filled))}
function quotaError(rows,owner){let lim=planLimits[brands[owner].plan];if(lim.locations&&brands[owner].branches.length>lim.locations)return tr(`Cette enseigne compte ${brands[owner].branches.length} succursales; le forfait en prévoit ${lim.locations}. Adaptez les succursales ou simulez un autre forfait.`,`This brand has ${brands[owner].branches.length} locations; the plan allows ${lim.locations}. Adjust locations or simulate another plan.`);let remaining=lim.shifts===null?null:Math.max(0,lim.shifts-planUsage(owner));let n=freshBrandRows(rows,owner).length;if(remaining!==null&&n>remaining)return tr(`Cette série ajouterait ${n} quarts. Il reste ${remaining} quarts dans le forfait simulé ce mois-ci. Réduisez la série ou choisissez un autre forfait. Aucun quart n’a été publié.`,`This series would add ${n} shifts. Your simulated plan has ${remaining} shifts left this month. Reduce the series or choose another plan. No shifts have been published.`);return null}
function plans(){let b=brands[tenant],used=planUsage(tenant),limit=planLimits[b.plan].shifts;let names=[tr('Pilote','Pilot'),tr('Réseau','Network'),tr('Grande chaîne','Enterprise')];return heading(tr('Abonnement entreprise','Business subscription'),tr('Le bon forfait pour votre réseau.','The right plan for your network.'),tr('Proposition à valider · Dollars canadiens, avant taxes · Aucun achat réel.','Proposal to validate · Canadian dollars, before taxes · No real purchase.'))+`<div class="notice"><strong>${tr('Consommation simulée','Simulated usage')} · ${names[b.plan]}</strong><br>${used} ${limit===null?tr('quarts publiés · volume contractuel à définir','shifts published · contractual volume to define'):tr(`sur ${limit} quarts publiés ce mois-ci`, `of ${limit} shifts published this month`)}<br><span class="sub">${tr('Compteur de cette session uniquement. Les exemples initiaux ne comptent pas.','This session’s counter only. Initial examples do not count.')}</span></div><div class="grid">${names.map((n,i)=>`<section class="card plan-card ${b.plan===i?'selected':''}"><span class="badge">${n}</span><div class="plan section">${i===2?tr('Sur devis','Custom quote'):(i===0?'299':'799')+' $'} ${i===2?'':'<small>/ '+tr('mois','month')+'</small>'}</div><p>${i===2?tr('Réseaux de plus de 15 succursales','Networks with more than 15 locations'):tr(`Jusqu’à ${planLimits[i].locations} succursales`,`Up to ${planLimits[i].locations} locations`)}</p><strong class="plan-volume">${i===2?tr('Volume négocié au contrat','Contracted volume'):planLimits[i].shifts+' '+tr('quarts / mois','shifts / month')}</strong><p class="sub">${tr('Quota partagé entre toutes les succursales de l’enseigne.','Quota shared across all of the brand’s locations.')}</p><details class="plan-details"><summary>${tr('Voir les détails du forfait','View plan details')} ${n}</summary><div class="section"><h3>${tr('Ce qui est proposé','What is proposed')}</h3><ul class="features"><li>${tr('Portail à votre nom et à vos couleurs','Portal with your name and colours')}</li><li>${tr('Diffusion vers le réseau employés Dispo','Distribution to the Dispo worker network')}</li><li>${tr('Quarts récurrents et publication multisuccursales','Recurring shifts and multi-location posting')}</li><li>${tr('Modèles de postes réutilisables','Reusable job templates')}</li><li>${tr('Lien partageable et module pour votre site','Shareable link and website embed')}</li>${i>0?`<li>${tr('Gestion des accès par succursale — à développer','Location-level access management — to develop')}</li><li>${tr('Rapports consolidés — à développer','Consolidated reporting — to develop')}</li>`:''}${i===2?`<li>${tr('Déploiement et intégrations à définir ensemble','Rollout and integrations to scope together')}</li>`:''}</ul><h3>${tr('Volume et dépassement','Volume and overages')}</h3><p>${i===2?tr('Le contrat fixera les succursales, le volume mensuel et le niveau de service. Aucun volume illimité garanti à ce stade. La démo n’impose pas de quota mensuel à ce choix; elle conserve un maximum de 1 500 quarts par opération.','The contract will define locations, monthly volume and service level. No unlimited volume is guaranteed at this stage. This demo choice has no monthly quota; the 1,500-shift limit per operation remains.'):tr(`Le forfait comprend ${planLimits[i].shifts} nouveaux quarts publiés par mois, pour toute l’enseigne. Une série dépassant le solde est bloquée dans la simulation avant publication. Aucun dépassement payant automatique.`, `The plan includes ${planLimits[i].shifts} new shifts published monthly across the brand. A series exceeding the balance is blocked in the simulation before publishing. No automatic paid overages.`)}</p><h3>${tr('Mise en place et facturation','Setup and billing')}</h3><p>${tr('Personnalisation avancée, domaine, intégrations et accompagnement : frais à chiffrer au devis. Conditions trimestrielles et annuelles à définir. Aucun paiement de salaire par Dispo.','Advanced customization, domain, integrations and support: fees to quote. Quarterly and annual terms to define. Dispo does not process wages.')}</p><p class="sub">${tr('Cette fiche décrit l’offre envisagée. Les comptes sécurisés, la facturation et les services indiqués « à développer » ne sont pas actifs.','This describes the proposed offer. Secure accounts, billing and services marked “to develop” are not active.')}</p></div></details><button class="${b.plan===i?'':'secondary'}" onclick="selectBusinessPlan(${i})">${b.plan===i?tr('✓ Choix de démonstration','✓ Demo selection'):tr('Simuler ce choix','Simulate selection')}</button></section>`).join('')}</div><section class="card section"><h2>${tr('Comment compte-t-on un quart ?','How is a shift counted?')}</h2><p><strong>${tr('1 poste + 1 date + 1 créneau + 1 succursale = 1 quart publié.','1 role + 1 date + 1 time slot + 1 location = 1 published shift.')}</strong></p><p>${tr('Exemple : un plongeur, 5 jours, 2 créneaux par jour, dans 3 succursales = 30 quarts. Demander 3 personnes pour le même quart reste 1 quart, avec 3 places.','Example: a dishwasher, 5 days, 2 time slots daily, at 3 locations = 30 shifts. Requesting 3 people for one shift still counts as 1 shift, with 3 openings.')}</p><details><summary>${tr('Modèles, répétitions et remise à zéro','Templates, repeats and reset')}</summary><ul class="features"><li>${tr('Créer ou charger un modèle ne consomme aucun quart.','Creating or loading a template uses no shifts.')}</li><li>${tr('Les répétitions sont comptées lorsqu’elles sont publiées, même pour des dates futures.','Repeats are counted when published, even for future dates.')}</li><li>${tr('Un doublon actif ignoré ne compte pas. Fermer un quart ne rend pas le crédit; le republier comme nouveau quart consomme une nouvelle unité.','An ignored active duplicate does not count. Closing a shift does not restore credit; republishing it as a new shift uses a new unit.')}</li><li>${tr('Quota mensuel proposé : remise à zéro au début du mois civil, sans report. Les quarts déjà publiés restent affichés.','Proposed monthly quota: resets at the start of the calendar month, without rollover. Published shifts remain listed.')}</li><li>${tr('Dans cette démo, recharger la page réinitialise les publications et le compteur. Le contrôle durable côté serveur reste à construire.','In this demo, reloading resets posts and usage. Persistent server-side enforcement must still be built.')}</li></ul></details></section><div class="notice"><strong>${tr('Pourquoi pas « illimité » dès maintenant ?','Why not offer “unlimited” immediately?')}</strong><br>${tr('Un grand volume est envisageable avec une architecture adaptée, mais il faut mesurer le trafic, les recherches, les photos, les notifications et le soutien. L’offre grande chaîne reste sur devis jusqu’aux essais de charge et à la validation des coûts.','High volume is possible with suitable architecture, but traffic, searches, photos, notifications and support must be measured. Enterprise stays custom-quoted until load testing and cost validation.')}</div>`}
function selectBusinessPlan(i){brands[tenant].plan=i;render();toast(tr('Choix simulé — aucun paiement. Le compteur de publication est conservé.','Simulated choice — no payment. Publishing usage is preserved.'))}

render();

function openBrandPlanner(id){const j=jobs.find(x=>x.id===id&&x.brand===tenant);const owner=tenant;DispoPlanner.open({lang,key:'brand:'+owner,employee:false,branches:brands[owner].branches,roles:roles().map((label,i)=>({key:String(i),label})),scopes:true,validate:rows=>quotaError(rows,owner),prefill:j?{roleKey:String(j.role),rate:j.pay,count:j.count||1,branches:brands[owner].branches.includes(j.city)?[j.city]:[],from:j.date,to:j.date,slots:[{start:j.start,end:j.end}],sameTeam:j.sameTeam||false,scope:j.scope}:undefined,onPublish(rows){let err=quotaError(rows,owner);if(err){toast(err);return}let series=(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),added=0;for(const r of rows){if(jobs.some(j=>j.brand===owner&&j.role===Number(r.roleKey)&&j.city===r.city&&j.date===r.date&&j.start===r.start&&j.end===r.end&&!j.filled))continue;jobs.push({id:Date.now()+added,brand:owner,role:Number(r.roleKey),city:r.city,date:r.date,start:r.start,end:r.end,pay:r.rate,count:r.count,scope:r.scope,sameTeam:r.sameTeam,series,publishedMonth:planMonth(),filled:false});added++}render();toast(tr(`${added} quarts publiés; ${rows.length-added} doublons actifs ignorés.`,`${added} shifts published; ${rows.length-added} active duplicates skipped.`))}})}
function seriesControls(){let groups=[...new Set(jobs.filter(j=>j.brand===tenant&&j.series).map(j=>j.series))];return groups.length?`<details class="section"><summary>${tr('Gérer les séries','Manage series')}</summary>${groups.map(g=>{let list=jobs.filter(j=>j.brand===tenant&&j.series===g);return `<div class="listrow"><span>${roles()[list[0].role]} · ${list.length} ${tr('quarts','shifts')}</span><button class="secondary small" onclick="closeBrandSeries('${g}')">${tr('Fermer la série','Close series')}</button></div>`}).join('')}</details>`:''}
function closeBrandSeries(id){jobs.filter(j=>j.brand===tenant&&j.series===id).forEach(j=>j.filled=true);render()}
function openWorkerPlanner(id){let p=workerAvailability.find(a=>a.id===id);DispoPlanner.open({lang,key:'network:employee',employee:true,branches:['Saint-Sauveur'],roles:roles().map((label,i)=>({key:String(i),label})),prefill:p?{roleKey:p.roleKey,rate:p.rate,from:p.date,to:p.date,slots:[{start:p.start,end:p.end}]}:undefined,onPublish(rows){let series=(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),added=0;for(const r of rows){if(workerAvailability.some(x=>x.date===r.date&&x.start===r.start&&x.end===r.end&&x.roleKey===r.roleKey&&!x.closed))continue;workerAvailability.push({...r,id:(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),series,closed:false});added++}render();toast(tr(`${added} disponibilités ajoutées; ${rows.length-added} doublons ignorés.`,`${added} availability slots added; ${rows.length-added} duplicates skipped.`))}})}
function closeWorkerSlot(id){workerAvailability.find(x=>x.id===id).closed=true;render()}
function closeWorkerSeries(id){workerAvailability.filter(x=>x.series===id).forEach(x=>x.closed=true);render()}
function availabilityPanel(){const groups=[...new Set(workerAvailability.map(x=>x.series))];return `<section class="card section"><div class="row spread"><div><h2>${tr('Mes disponibilités','My availability')}</h2><p>${tr('Planifiez votre mois. Vous restez libre d’accepter chaque offre.','Plan your month. You remain free to accept each offer.')}</p></div><button onclick="openWorkerPlanner()">+ ${tr('Planifier / mes modèles','Plan / my templates')}</button></div>${groups.map(g=>{let list=workerAvailability.filter(x=>x.series===g);return `<details><summary>${list.length} ${tr('créneaux','slots')} · ${list[0].date}</summary><button class="secondary small" onclick="closeWorkerSeries('${g}')">${tr('Fermer cette série','Close this series')}</button>${list.map(a=>`<div class="listrow"><div><strong>${a.date} · ${a.start}–${a.end}</strong><div class="sub">${roles()[Number(a.roleKey)]}</div></div><div class="row"><button class="secondary small" onclick="openWorkerPlanner('${a.id}')">${tr('Réutiliser / enregistrer','Reuse / save')}</button>${a.closed?`<span class="badge gray">${tr('Plus disponible','Unavailable')}</span>`:`<button class="secondary small" onclick="closeWorkerSlot('${a.id}')">${tr('Clôturer','Close')}</button>`}</div></div>`).join('')}</details>`}).join('')}</section>`}

function profileSkillError(e){return e.message==='licence'?tr('Choisis au moins une classe de permis.','Choose at least one licence class.'):tr('Précise ton autre compétence.','Specify your other skill.')}
function businessProfile(){const b=brands[tenant];return heading(tr('Mon entreprise','My business'),tr('Profil entreprise','Business profile'),tr('Précise les compétences recherchées dans tes équipes.','Specify skills sought for your teams.'))+`<form class="card" onsubmit="saveBusinessProfile(event)"><label>${tr('Nom de l’entreprise','Business name')}<input name="name" maxlength="60" required value="${esc(b.name)}"></label><label>${tr('Téléphone (10 chiffres, avec ou sans tirets)','Phone (10 digits, with or without hyphens)')}<input name="phone" type="tel" placeholder="450-555-1234" value="${esc(b.phone||'')}"></label>${DispoStandards.skillsForm(b,true,lang)}${DispoStandards.badge('employer:'+tenant,lang)}${DispoStandards.encourage(lang)}<button>${tr('Enregistrer mon profil','Save my profile')}</button></form><button class="profile-delete" onclick="deleteBusinessProfile()">${tr('Effacer mon profil entreprise','Delete my business profile')}</button>`}
function saveBusinessProfile(e){e.preventDefault();const f=new FormData(e.target),raw=String(f.get('phone')||'').trim(),phone=DispoStandards.phone(raw);if(raw&&!phone)return toast(tr('Entre 4505551234 ou 450-555-1234 (10 chiffres).','Enter 4505551234 or 450-555-1234 (10 digits).'));try{const skills=DispoStandards.readSkills(f);Object.assign(brands[tenant],skills,{name:String(f.get('name')).trim(),phone:phone||''});render();toast(tr('Profil enregistré dans cette démo.','Profile saved in this demo.'))}catch(error){toast(profileSkillError(error))}}
function networkProfileForm(){return `<details class="card section"><summary>${tr('Mon profil employé','My worker profile')}</summary><form onsubmit="saveNetworkProfile(event)"><label>${tr('Téléphone (10 chiffres, avec ou sans tirets)','Phone (10 digits, with or without hyphens)')}<input name="phone" type="tel" placeholder="450-555-1234" value="${esc(networkProfile.phone||'')}"></label>${DispoStandards.skillsForm(networkProfile,false,lang)}${DispoStandards.encourage(lang)}<button>${tr('Enregistrer mon profil','Save my profile')}</button></form><button class="profile-delete" onclick="deleteNetworkProfile()">${tr('Effacer mon profil','Delete my profile')}</button></details>`}
function saveNetworkProfile(e){e.preventDefault();const f=new FormData(e.target),raw=String(f.get('phone')||'').trim(),phone=DispoStandards.phone(raw);if(raw&&!phone)return toast(tr('Entre 4505551234 ou 450-555-1234 (10 chiffres).','Enter 4505551234 or 450-555-1234 (10 digits).'));try{Object.assign(networkProfile,DispoStandards.readSkills(f),{phone:phone||''});render();toast(tr('Profil enregistré.','Profile saved.'))}catch(error){toast(profileSkillError(error))}}
function deleteBusinessProfile(){const owner=tenant;DispoStandards.confirmDelete(tr('Le profil de cette enseigne, ses coordonnées, ses quarts, ses candidatures et ses modèles seront effacés dans cette démo. Les autres enseignes seront conservées.','This demo brand’s profile, contacts, shifts, applications and templates will be cleared. Other brands will be kept.'),()=>{localStorage.removeItem('dispo-post-templates-v1:brand:'+owner);const ids=jobs.filter(j=>j.brand===owner).map(j=>j.id);jobs=jobs.filter(j=>j.brand!==owner);applications=applications.filter(a=>!ids.includes(a.job));brands[owner]={name:'',letter:'',color:'#126953',branches:[],plan:0,deleted:true};consent=null;reviewDraft=null;tab='profile';render()},lang)}
function deletedBrandPage(){return `<section class="card"><h1>${tr('Profil entreprise effacé','Business profile deleted')}</h1><p>${tr('Les données de cette enseigne ont été retirées de la démo. Les autres enseignes restent accessibles dans le menu du haut.','This brand’s data has been removed from the demo. Other brands remain available in the top menu.')}</p><button onclick="newBusinessProfile()">${tr('Créer un nouveau profil','Create a new profile')}</button></section>`}
function newBusinessProfile(){brands[tenant]={name:tr('Nouvelle entreprise','New business'),letter:'N',color:'#126953',branches:[],plan:0,skillIds:[]};tab='profile';render()}
function deleteNetworkProfile(){DispoStandards.confirmDelete(tr('Ton profil employé, tes disponibilités, tes candidatures et tes modèles dans ce portail seront effacés.','Your worker profile, availability, applications and templates in this portal will be cleared.'),()=>{localStorage.removeItem('dispo-post-templates-v1:network:employee');networkProfile={skillIds:[],licenceClasses:[],phone:''};workerAvailability=[];applications=[];consent=null;reviewDraft=null;render();toast(tr('Profil employé de démonstration effacé.','Demo worker profile deleted.'))},lang)}
function applicationReviewControls(a,actor){const j=jobs.find(j=>j.id===a.job);if(!j)return '';const r=a[actor+'Review'];if(r)return DispoStandards.reviewSummary(r,actor==='employer'?'employee':'employer',lang);return a.completed?`<button class="secondary small" onclick="startBusinessReview(${a.job},'${actor}')">${tr(actor==='employer'?'Évaluer le travailleur':'Évaluer l’employeur',actor==='employer'?'Review worker':'Review employer')}</button>`:`<button class="secondary small" onclick="completeBusinessShift(${a.job})">${tr('Simuler le quart terminé','Simulate completed shift')}</button>`}
function completeBusinessShift(id){const a=applications.find(a=>a.job===id);if(a){a.completed=true;render()}}
function startBusinessReview(id,actor){const a=applications.find(a=>a.job===id),j=jobs.find(j=>j.id===id);if(!a?.completed||!j||a[actor+'Review']||(actor==='employer'&&j.brand!==tenant))return;reviewDraft={id,actor};render();document.querySelector('#business-review')?.scrollIntoView({behavior:'smooth'})}
function businessReviewForm(){if(!reviewDraft)return '';return `<form class="card section" id="business-review" onsubmit="saveBusinessReview(event)"><h3>${tr('Mon avis sur ce quart','My shift review')}</h3>${DispoStandards.reviewFields(reviewDraft.actor==='employer'?'employee':'employer',lang)}<p class="sub">${tr('Avis fictif. Un avis ne conditionne jamais le paiement.','Demo review. Payment never depends on a review.')}</p><button>${tr('Enregistrer mon avis','Save my review')}</button><button type="button" class="secondary" onclick="reviewDraft=null;render()">${tr('Annuler','Cancel')}</button></form>`}
function saveBusinessReview(e){e.preventDefault();if(!reviewDraft)return;const {id,actor}=reviewDraft,a=applications.find(a=>a.job===id),j=jobs.find(j=>j.id===id);if(!a?.completed||!j||a[actor+'Review'])return;try{const review=DispoStandards.readReview(new FormData(e.target),actor==='employer'?'employee':'employer');a[actor+'Review']=review;DispoStandards.addReview(actor==='employer'?'worker:network-alex':'employer:'+j.brand,actor+':'+id,review);reviewDraft=null;render();toast(tr('Avis fictif enregistré; classement actualisé.','Demo review saved; ranking updated.'))}catch{toast(tr('Choisis de 1 à 5 étoiles.','Choose 1 to 5 stars.'))}}
function networkReviews(){return applications.length?`<section class="card section"><h2>${tr('Mes quarts et mes avis','My shifts and reviews')}</h2>${applications.map(a=>{const j=jobs.find(j=>j.id===a.job);return j?`<div class="listrow"><div>${esc(brands[j.brand].name)} · ${roles()[j.role]}</div>${applicationReviewControls(a,'employee')}</div>`:''}).join('')}${reviewDraft?.actor==='employee'?businessReviewForm():''}</section>`:`<section class="card section"><h2>${tr('Mes avis','My reviews')}</h2>${DispoStandards.reviewPreview('employer',lang)}</section>`}
